const path = require('path');
const { execFileSync } = require('child_process');

module.exports = function ({ assertEqual }) {
  const cli = path.join(__dirname, '..', 'bin', 'cli.js');
  const fixture = path.join(__dirname, 'fixtures', 'order-a.json');

  const out = execFileSync('node', [cli, fixture], { encoding: 'utf8' });
  const expected = [
    'INVOICE ORD-A',
    'ITEM Books qty=1 billable_kg=2.00 tier=small amount=8.00',
    'ITEM Monitor qty=1 billable_kg=10.80 tier=medium amount=15.00',
    'SHIPPING zone=domestic amount=4.50',
    'SUBTOTAL 23.00',
    'TAX 1.61',
    'TOTAL 29.11',
    '',
  ].join('\n');
  assertEqual(out, expected, 'cli prints the ORD-A invoice exactly');

  let code = 0;
  try {
    execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'no-such-order.json')], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    code = e.status;
  }
  assertEqual(code, 1, 'a missing order file exits 1');

  // SPEC-T3.md worked example 1 — SAVE10
  const outB = execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'order-b.json')], { encoding: 'utf8' });
  const expectedB = [
    'INVOICE ORD-B',
    'ITEM Books qty=1 billable_kg=2.00 tier=small amount=8.00',
    'ITEM Monitor qty=1 billable_kg=10.80 tier=medium amount=15.00',
    'SHIPPING zone=domestic amount=4.50',
    'SUBTOTAL 23.00',
    'DISCOUNT code=SAVE10 amount=2.30',
    'TAX 1.45',
    'TOTAL 26.65',
    '',
  ].join('\n');
  assertEqual(outB, expectedB, 'cli prints the ORD-B (SAVE10) invoice exactly');

  // SPEC-T3.md worked example 2 — FREESHIP
  const outC = execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'order-c.json')], { encoding: 'utf8' });
  const expectedC = [
    'INVOICE ORD-C',
    'ITEM Desk qty=1 billable_kg=30.00 tier=large amount=41.00',
    'SHIPPING zone=international amount=0.00',
    'SUBTOTAL 41.00',
    'DISCOUNT code=FREESHIP amount=22.00',
    'TAX 2.87',
    'TOTAL 43.87',
    '',
  ].join('\n');
  assertEqual(outC, expectedC, 'cli prints the ORD-C (FREESHIP) invoice exactly');

  // SPEC-T3.md worked example 3 — unknown code
  let bogusCode = 0;
  let bogusStdout = '';
  let bogusStderr = '';
  try {
    bogusStdout = execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'order-bogus-discount.json')], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    bogusCode = e.status;
    bogusStdout = e.stdout;
    bogusStderr = e.stderr;
  }
  assertEqual(bogusCode, 2, 'an unknown discount code exits 2');
  assertEqual(bogusStdout, '', 'an unknown discount code prints nothing to stdout');
  assertEqual(bogusStderr, 'parcel-billing: unknown discount code: BOGUS\n', 'an unknown discount code prints the exact stderr message');
};

